const userMessage = String($('When chat message received').first().json.chatInput ?? '').trim();
const generated = String($json.output ?? $json.text ?? '').trim();

const asksLiveAvailability = /\b(available|availability|vacancy|vacant|open rooms?|rooms? open|bakante|may bakante|may available|meron(?:g)? bakante|may room pa)\b/i.test(userMessage);
const startsBooking = /\b(book|booking|reserve|reservation|mag-?book|magpa-?book|pa-?book|mag-?reserve|pa-?reserve|gusto ko (?:sanang )?kumuha ng room)\b/i.test(userMessage);
const isMetaAnalysis = /explained.+rule\?|friendly\s*\/\s*concise\?|checklist|criteria met|rules? followed/i.test(generated);
const looksTruncated = !generated || isMetaAnalysis || /\b(as|because|and|or|but|are|is|to|for|the|a|an)\s*$/i.test(generated);

if (asksLiveAvailability) {
  return [{ json: { output: 'Maibabahagi ko ang impormasyon tungkol sa mga kuwarto, pero wala akong access sa live availability at hindi ako makakapagkumpirma ng reservation. Kailangang i-check ng resort staff ang napili mong petsa at final quotation. Gusto mo bang kunin ko ang arrival date, departure date, bilang ng adults, at bilang at edad ng mga bata para sa staff follow-up?', handoff_required: true, safety_override: 'live_availability' } }];
}

if (startsBooking) {
  return [{ json: { output: 'Sige, tutulungan kitang ihanda ang booking request. Kailangan pa ring kumpirmahin ng resort staff ang availability at final price. Ano ang preferred arrival date mo?', handoff_required: false, safety_override: 'booking_intake_start' } }];
}

if (looksTruncated) {
  return [{ json: { output: 'Pasensya, hindi ako nakabuo ng kumpletong sagot. Pakisubukang ulitin ang tanong o humiling ng tulong mula sa resort staff.', handoff_required: true, safety_override: isMetaAnalysis ? 'meta_analysis_output' : 'incomplete_model_output' } }];
}

return [{ json: { output: generated, handoff_required: false, safety_override: null } }];
